import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_in_rate_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_keeps_last_input_record_then_sorts():
    events = parse_transcript_log(["a,9,0", "c,1,1", "b,2,0", "a,2,1"])
    assert dedupe_transcripts(events) == [events[1], events[3], events[2]]


def test_parse_skips_comments_and_strips_fields():
    lines = ["", " \t", "  # header", "  a , 1 , 0 ", " b , 2 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": False},
        {"id": "b", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize('bad', ['x,1', 'x,1,0,extra', 'x,day,1'])
def test_parse_error_reports_physical_line(bad):
    with pytest.raises(ValueError, match=r'line 4\b'):
        parse_transcript_log(['   ', ' # comment', 'a,1,1', bad])


def test_daily_counts_include_gaps_and_ignore_outside_range():
    events = parse_transcript_log(['a,0,1', 'b,2,1', 'c,2,1', 'd,3,0', 'e,4,1'])
    assert daily_flag_counts(events, 1, 3) == [0, 2, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_trailing_window_boundaries():
    assert [flags_in_window([4, 1, 2], days) for days in (0, 2, 5)] == [0, 3, 7]


def test_summary_weights_transcripts_and_uses_calendar_days():
